/**
 * /integrations/ —— 渠道集成索引
 *
 * 用法（BYOL）：商家在供应商处已有账号，这里只回答三个问题 ——
 *   ① 每条通道现在能自助接哪几家（`CHANNELS` × `INTEGRATIONS`）
 *   ② 每家分别要准备什么（字段清单在各自详情页）
 *   ③ 接上之后我这边还要做什么（详情页的「What stays on your side」按通道分写）
 *
 * 🔴 **两个数字口径不得混**（本页按通道分开写）：
 *    · 「自助接入 X 家」= 该通道下 `INTEGRATIONS` 的条目数（`INTEGRATION_STATS.byChannel`）；
 *    · 「适配器库覆盖 Y 家」= quick-sms SDK 的 `OutboundSender` SPI 实现数，
 *      **这是短信适配器数，只适用于 SMS 通道**，不得挪到邮件/WhatsApp 名下。
 *    把后者写成「支持 Y 家供应商自助接入」就是虚标，且与 /messaging 页的口径会打架。
 *
 * 📌 **本页自 2026-10-14 起收录三通道**（此前只收 `channel: CHANNEL_SMS`，理由是控制台
 *    当时没有通道选择器）。控制台三通道入口上线后该理由作废 —— 线上 bundle 实证见
 *    `data/integrations.js` 文件头。分组的通道标签与说明取自 `CHANNELS`，
 *    卡片角标取自每条自己的 `channel`，**两处必须同源**，否则会出现「Email 组里飘着一张 SMS 卡」。
 *
 * 🔴 红线（BSP 文案稿 §6）：本页能力描述限定在**已声明的通道**内。通道专属能力
 *    （路由切换 / 分号码限速 / 分段计费）在列表里必须带通道限定语，不得写成三通道通用。
 *
 * @author 恒哥
 * @since 2026-10-12
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../../components/Layout';
import SEO from '../../components/SEO';
import { MESSAGING_PRODUCT_NAME, MESSAGING_CONSOLE_URL, MESSAGING_CONNECTIONS_URL, DOCS_URL } from '../../constants/brand';
import { CHANNELS, INTEGRATION_STATS, channelMeta, integrationsInChannel } from '../../data/integrations';
import '../../styles/marketing.css';
import T from '../../i18n/LocalizedText';
import { usePageI18n } from '../../i18n';

export default function IntegrationsIndex(pageContext) {
  const { locale, localePath } = usePageI18n(pageContext);

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title="Provider integrations — bring your own accounts"
        description={`${MESSAGING_PRODUCT_NAME} connects to the SMS, email and WhatsApp provider accounts you already hold. See exactly which credentials each one needs, what we configure, and what stays on your side.`}
        pathname="/integrations/"
        softwareApp={false} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="integrations.001">Bring your own account</T></span>
          <h1><T id="integrations.002">Use the SMS, email and WhatsApp accounts you already pay for</T></h1>
          <p className="mk-lead">
            <T id="integrations.003">{MESSAGING_PRODUCT_NAME} never sells you message credits. You keep your existing
            provider account, your negotiated rate and your invoice &mdash; and paste that
            account&rsquo;s API credentials here. We handle routing, pacing and the send log.
          </T></p>
          <div className="mk-actions">
            <a className="mk-btn mk-btn-primary" href={MESSAGING_CONNECTIONS_URL}><T id="integrations.004">
              Add a connection
            </T></a>
            <Link className="mk-btn mk-btn-secondary" to={localePath("/platform/")}><T id="integrations.005">
              How {MESSAGING_PRODUCT_NAME} works
            </T></Link>
          </div>
        </header>

        <div className="mk-scope">
          <T id="integrations.006"><strong>Why bring your own.</strong> If we resold message volume we would have to sit
          between you and your provider: our margin, our routing choices, our support queue. We do
          none of that. Your account, your quota and your negotiated rate stay yours, and the
          relationship with your provider stays in your name.
        </T></div>

        {CHANNELS.map((ch) => {
          const items = integrationsInChannel(ch.id);
          return (
            <section className="mk-section" key={ch.id}>
              <h2>
                <T id="integrations.007">{ch.label} &mdash; {items.length} provider{items.length === 1 ? '' : 's'} available now
              </T></h2>
              <p className="mk-section-lead">
                <T id="integrations.008">{ch.flow} Self-service: create the connection in the console yourself, no
                conversation with us required. Each page lists the exact credential fields that
                provider needs.
              </T></p>
              <div className="mk-grid">
                {items.map((i) => (
                  <article className="mk-card" key={i.slug}>
                    <span className="mk-card-tag">{channelMeta(i.channel).label}</span>
                    <h3>
                      <Link to={`/integrations/${i.slug}/`}>{i.name}</Link>
                    </h3>
                    <p>{i.summary}</p>
                    <Link className="mk-card-link" to={`/integrations/${i.slug}/`}>
                      <T id="integrations.009">{i.name} setup &rarr;
                    </T></Link>
                  </article>
                ))}
              </div>
            </section>
          );
        })}

        <section className="mk-section">
          <h2><T id="integrations.010">Beyond this list</T></h2>
          <p className="mk-section-lead"><T id="integrations.011">
            Everything above is wired end-to-end in the console, and it is the same set you see when
            you open the connection page. What sits behind it is a per-channel adapter library, which
            is why a provider we do not list yet is a build rather than a rewrite.
          </T></p>
          <ul className="mk-list">
            <li>
              <T id="integrations.012"><strong>Two different numbers, deliberately.</strong> &ldquo;Available now&rdquo; counts
              provider accounts you can connect yourself, across all three channels (
              {INTEGRATION_STATS.byChannel.SMS} on SMS, {INTEGRATION_STATS.byChannel.EMAIL} on email,{' '}
              {INTEGRATION_STATS.byChannel.WHATSAPP} on WhatsApp &mdash; {INTEGRATION_STATS.selfService}{' '}
              in total). The <strong>{INTEGRATION_STATS.sdkAdapters}</strong> figure counts SMS{' '}
              <em>adapters</em> in the SDK, which is a different thing: adapters are per-vendor code
              paths, some of them address the same vendor&rsquo;s regional endpoints, most are not
              self-service yet, and the number says nothing about email or WhatsApp.
            </T></li>
            <li>
              <T id="integrations.013"><strong>Need one that is not listed?</strong> Open the connection page in the console
              and register the request there, so it is counted rather than lost in an inbox.
            </T></li>
            <li>
              <T id="integrations.014"><strong>Custom or private gateways</strong> are a different job again &mdash;
              endpoints, signing and status mapping have to be built per provider. That is
              development work, not a configuration checkbox.
            </T></li>
          </ul>
          <div className="mk-actions">
            <a className="mk-btn mk-btn-secondary" href={DOCS_URL}><T id="integrations.015">
              Read the docs
            </T></a>
            <Link className="mk-btn mk-btn-secondary" to={localePath("/guides/byol/")}><T id="integrations.016">
              What BYOL means in practice
            </T></Link>
          </div>
        </section>

        <section className="mk-section">
          <h2><T id="integrations.017">What every connection gets</T></h2>
          <ul className="mk-list">
            <li>
              <T id="integrations.018"><strong>Credential custody.</strong> AES-256-GCM at rest, masked in the console,
              plaintext never logged and never returned to the browser. Rotate or delete at any
              time &mdash; the credentials are yours.
            </T></li>
            <li>
              <T id="integrations.019"><strong>A send log for every message.</strong> Metadata per send &mdash; time,
              recipient, provider, channel, status, error code &mdash; on all three channels. Message
              bodies are never stored, so the log is safe to keep.
            </T></li>
            <li>
              <T id="integrations.020"><strong>Delivery receipts, normalized.</strong> Where the provider reports delivery
              back (every SMS provider, Resend on email, Meta on WhatsApp), the outcome is
              normalized into one status and can be pushed to an endpoint you configure.
            </T></li>
            <li>
              <T id="integrations.021"><strong>One error vocabulary.</strong> Provider error codes are normalized so the same
              failure reads the same way across providers and channels, with the raw provider code
              kept alongside.
            </T></li>
            <li>
              <T id="integrations.022"><strong>Route selection and failover (SMS channel).</strong> Bind several providers
              and sender numbers to one route, with priority and weight, so a provider outage does
              not stop the send.
            </T></li>
            <li>
              <T id="integrations.023"><strong>Pacing to the quota you actually have (SMS channel).</strong> Each connection
              has a send rate you control; we queue to that rate rather than firing as fast as the
              provider will accept.
            </T></li>
          </ul>
        </section>

        <section className="mk-section">
          <h2><T id="integrations.024">What stays in your name</T></h2>
          <p className="mk-section-lead"><T id="integrations.025">
            Because we never resell your traffic, there is nothing in the middle of the money
            &mdash; and nothing in the middle of your relationship with your provider.
          </T></p>
          <ul className="mk-list mk-list-plain">
            <li><T id="integrations.026">Your negotiated rate and your provider invoice, untouched</T></li>
            <li><T id="integrations.027">
              Sender IDs, numbers and short codes on SMS; verified domains on email; the business
              account and number on WhatsApp
            </T></li>
            <li><T id="integrations.028">Your volume commitments, which never move to a balance we hold</T></li>
            <li><T id="integrations.029">Your relationships with the carriers and networks you already send through</T></li>
          </ul>
          <div className="mk-actions">
            <a className="mk-btn mk-btn-primary" href={MESSAGING_CONSOLE_URL}><T id="integrations.030">
              Create a connection
            </T></a>
            <Link className="mk-btn mk-btn-secondary" to={localePath("/platform/pricing/")}><T id="integrations.031">
              See pricing
            </T></Link>
          </div>
        </section>
      </div>
    </Layout>
  );
}
